-- Pitanga Store: base fictícia para os exercícios de análise de dados (MySQL 8)
-- Como usar: MySQL Workbench > File > Open SQL Script > abra este arquivo > Execute (raio).
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS pitanga_store;
CREATE DATABASE pitanga_store CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE pitanga_store;

CREATE TABLE clientes (
  cliente_id      INT          NOT NULL PRIMARY KEY,
  nome            VARCHAR(100) NOT NULL,
  email           VARCHAR(150),
  cidade          VARCHAR(60),
  estado          CHAR(2),
  data_cadastro   DATE,
  canal_aquisicao VARCHAR(30)
);


CREATE TABLE produtos (
  produto_id     INT           NOT NULL PRIMARY KEY,
  nome_produto   VARCHAR(100)  NOT NULL,
  categoria      VARCHAR(30)   NOT NULL,
  preco_lista    DECIMAL(10,2) NOT NULL,
  custo_unitario DECIMAL(10,2) NOT NULL
);


CREATE TABLE pedidos (
  pedido_id       INT           NOT NULL PRIMARY KEY,
  cliente_id      INT           NOT NULL,
  data_pedido     DATE          NOT NULL,
  dispositivo     VARCHAR(20)   NOT NULL,
  forma_pagamento VARCHAR(30)   NOT NULL,
  status          VARCHAR(20)   NOT NULL,
  valor_frete     DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (cliente_id) REFERENCES clientes (cliente_id)
);


CREATE TABLE itens_pedido (
  item_id        INT           NOT NULL PRIMARY KEY,
  pedido_id      INT           NOT NULL,
  produto_id     INT           NOT NULL,
  quantidade     INT           NOT NULL,
  preco_unitario DECIMAL(10,2) NOT NULL,
  desconto_pct   DECIMAL(4,2)  NOT NULL,
  FOREIGN KEY (pedido_id)  REFERENCES pedidos (pedido_id),
  FOREIGN KEY (produto_id) REFERENCES produtos (produto_id)
);


CREATE TABLE teste_ab_checkout (
  sessao_id    VARCHAR(10)   NOT NULL PRIMARY KEY,
  grupo        VARCHAR(20)   NOT NULL,
  data_sessao  DATE          NOT NULL,
  dispositivo  VARCHAR(20)   NOT NULL,
  converteu    TINYINT       NOT NULL,
  valor_compra DECIMAL(10,2) NOT NULL
);


-- Tabela "suja" de propósito (situação 4): tudo como texto, com duplicatas.
CREATE TABLE clientes_crm_export_bruto (
  cliente_id      VARCHAR(20),
  nome            VARCHAR(100),
  email           VARCHAR(150),
  cidade          VARCHAR(60),
  estado          VARCHAR(5),
  data_cadastro   VARCHAR(20),
  canal_aquisicao VARCHAR(30)
);


-- Conferência: deve mostrar 10000 clientes, 54 produtos, 20004 pedidos.
SELECT (SELECT COUNT(*) FROM clientes) AS clientes, (SELECT COUNT(*) FROM produtos) AS produtos, (SELECT COUNT(*) FROM pedidos) AS pedidos;
